import itertools

numbers = list(range(1,17))
target = 34

# Find all 4-element subsets that sum to 34
subsets4 = []
for comb in itertools.combinations(numbers, 4):
    if sum(comb) == target:
        subsets4.append(comb)
print('4-element subsets count:', len(subsets4))
# Let's see if we can partition using 4-element subsets only
# Use backtracking
used = [False]*17
solution = []

def backtrack(start=0):
    if len(solution) == 4:
        # check all used
        return all(used[1:])
    # find first unused number
    first = None
    for i in range(1,17):
        if not used[i]:
            first = i
            break
    if first is None:
        return False
    # try subsets containing first
    for comb in subsets4:
        if first not in comb:
            continue
        ok = True
        for x in comb:
            if used[x]:
                ok = False
                break
        if not ok:
            continue
        for x in comb:
            used[x] = True
        solution.append(comb)
        if backtrack():
            return True
        solution.pop()
        for x in comb:
            used[x] = False
    return False

found = backtrack()
print('Found 4x4 partition:', found)
if found:
    print(solution)
